#!/usr/bin/env python3
"""Regenerates js/puzzles-data.js from data/puzzles.json (used when the game is opened via file://)."""
import json, os
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
d = json.load(open(os.path.join(root, 'data', 'puzzles.json')))
open(os.path.join(root, 'js', 'puzzles-data.js'), 'w').write(
    '/* generated by tools/build_data.py from data/puzzles.json */\nwindow.OOO_PUZZLES = ' + json.dumps(d, indent=1) + ';\n')
print('ok')
